    if (['Diterima', 'Disetujui', 'Terjadwal'].indexOf(x.status) < 0) galat_('Berkas pengajuan ini belum dinyatakan lengkap oleh admin sidang.');
    if (!pembimbing) galat_('Dosen pembimbing tidak ada di daftar dosen.');
    if (samaDosen_(ketua, anggota)) galat_('Ketua dan anggota penguji harus dosen yang berbeda.');
